  const mapLoanPurpose = (purpose) => {
    if (!purpose) return 'Other';

    const purposeMap = {
      'auto': 'Auto',
      'auto_purchase': 'auto_purchase',
      'auto_refinance': 'auto_refinance',
      'baby': 'Baby',
