import { axios } from "@pipedream/platform";

export const delay = (ms) => {
  return new Promise(resolve => setTimeout(resolve, ms));
};

export const isRetryable = (error) => {
  const retryableCodes = ['ECONNABORTED', 'ENOTFOUND', 'ECONNRESET', 'ETIMEDOUT'];
  const retryableStatuses = [429]; // Rate limiting
  const nonRetryableStatuses = [400, 401, 403, 404, 422]; // Client errors that won't change on retry

  if (retryableCodes.includes(error.code)) return true;
  if (retryableStatuses.includes(error.status)) return true;
  if (error.status >= 500) return true;
  if (nonRetryableStatuses.includes(error.status)) return false;

  return true; // Default to retry for unknown errors
};

export const makeRequestWithRetry = async (url, options = {}, maxRetries = 2, timeoutMs = 10000) => {
  const baseDelay = 1000; // Start with 1 second delay

  for (let attempt = 0; attempt <= maxRetries; attempt++) {
    try {
      console.log(`Attempt ${attempt + 1}/${maxRetries + 1} for ${url}`);

      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), timeoutMs);

      const response = await fetch(url, {
        ...options,
        signal: controller.signal
      });

      clearTimeout(timeoutId);

      console.log(`Request succeeded on attempt ${attempt + 1} with status ${response.status}`);
      return response;

    } catch (error) {
      const isLastAttempt = attempt === maxRetries;
      const isRetryableError = isRetryable(error);

      console.log(`Attempt ${attempt + 1} failed:`, error.message);

      if (isLastAttempt || !isRetryableError) {
        // If it's the last attempt or non-retryable error, throw the error
        throw error;
      }

      const delayMs = baseDelay * Math.pow(2, attempt);
      console.log(`Retrying in ${delayMs}ms...`);
      await delay(delayMs);
    }
  }
};

